wb = openpyxl.load_workbook(XLSX)
ws = wb["Где поесть"]
last = 1
for r in range(2, ws.max_row + 1):
    if any(c.value not in (None, "") for c in ws[r]):
        last = r
start = last + 1
for i, (name, desc, addr, district, coord, phone, hours) in enumerate(REST):
    r = start + i
    ws.cell(r, 1, "Рестораны")
    ws.cell(r, 3, name)
    ws.cell(r, 4, desc)
    ws.cell(r, 6, addr)
    ws.cell(r, 7, district)
    ws.cell(r, 8, coord)
    if phone: ws.cell(r, 14, phone)
    if hours: ws.cell(r, 15, hours)
wb.save(XLSX)
print(f"OK: ресторанов добавлено {len(REST)}, строки {start}–{start+len(REST)-1}")
